entries[159619] = { ["name"] = "Briny Barnacle", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Strength\nEquip: Your attacks have a chance to inflict Choking Brine, causing ( 4 * 6) Nature damage over 6 sec. If the target dies while inflicted with Choking Brine, it splashes to all targets within 8 yds.\nSell Price:" }
