entries[159622] = { ["name"] = "Hadal's Nautilus", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Intellect\nEquip: Your damaging spells have a chance to create a Waterspout at your target's location. The Waterspout erupts after 2 sec, dealing 23 Nature damage split among all nearby enemies. Deals increased damage when striking multiple targets. (3s cooldown)\nSell Price:" }
entries[159623] = { ["name"] = "Dead-Eye Spyglass", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Agility\nEquip: Your attacks have a chance to mark their targets as Dead Ahead. Attacking the marked target grants 7 Critical Strike for 10 sec, stacking up to 5 times.\nSell Price:" }
entries[159624] = { ["name"] = "Rotcrusted Voodoo Doll", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Intellect\nUse: Brandish the Voodoo Doll at your target, dealing 126 Shadow damage over 6 sec, and an additional 202 Shadow damage after 6 sec. (2 Min Cooldown)\nSell Price:" }
entries[159625] = { ["name"] = "Vial of Animated Blood", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 9 Mastery\nUse: Sip from the vial, gaining (3 * 9 ) Strength, which decays over 18 sec. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[159626] = { ["name"] = "Lingering Sporepods", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 [Agility or Strength]\nEquip: Your attacks and attacks made against you have a chance to trigger spores to grow for 4 sec before bursting. When they burst, they restore 75 health to you and deal 21 damage split among all nearby enemies. Deals increased damage when striking multiple targets.\nSell Price:" }
